const { createClient } = require('redis');
const redisUrl = String($env.REDIS_URL || '').trim();
const targetUrl = String($env.LANA_CATALOG_MIRROR_URL || 'http://lana-chatbot-api:8080/internal/catalog/snapshots').trim();
const mirrorKey = String($env.LANA_CATALOG_MIRROR_KEY || '').trim();
const ttlSeconds = Math.max(300, Math.min(172800, Number($env.CATALOG_REDIS_TTL_SECONDS || 7200)));
if (!redisUrl) throw new Error('REDIS_URL_REQUIRED');
if (mirrorKey.length < 32) throw new Error('LANA_CATALOG_MIRROR_KEY_REQUIRED');
const client = createClient({ url: redisUrl });
client.on('error', () => undefined);
let scanned = 0;
let mirrored = 0;
let rejected = 0;
const errors = {};
const addError = (code) => { errors[code] = (errors[code] || 0) + 1; };
try {
  await client.connect();
  for await (const batchOrKey of client.scanIterator({ MATCH: 'catalog:offer:*', COUNT: 100 })) {
    const keys = Array.isArray(batchOrKey) ? batchOrKey : [batchOrKey];
    for (const redisKey of keys) {
      scanned += 1;
      const raw = await client.get(redisKey);
      if (!raw) { rejected += 1; addError('SNAPSHOT_MISSING'); continue; }
      let snapshot;
      try { snapshot = JSON.parse(raw); } catch { rejected += 1; addError('SNAPSHOT_JSON_INVALID'); continue; }
      if (!snapshot || snapshot.schema_version !== 3) { rejected += 1; addError('SNAPSHOT_SCHEMA_INVALID'); continue; }
      const body = { schema_version: 1, source: 'N8N_POS_SNAPSHOT', ttl_seconds: ttlSeconds, snapshot };
      let delivered = false;
      let lastCode = 'APP_BRIDGE_FAILED';
      for (let attempt = 1; attempt <= 3 && !delivered; attempt += 1) {
        try {
          const response = await this.helpers.httpRequest({
            method: 'POST',
            url: targetUrl,
            headers: { 'x-lana-internal-key': mirrorKey, 'content-type': 'application/json' },
            body,
            json: true,
            timeout: 15000,
            returnFullResponse: true,
          });
          const status = Number(response.statusCode || 0);
          delivered = status >= 200 && status < 300;
          if (!delivered) lastCode = 'APP_HTTP_' + status;
        } catch (error) {
          lastCode = 'APP_REQUEST_FAILED';
          if (attempt < 3) await new Promise((resolve) => setTimeout(resolve, 250 * attempt));
        }
      }
      if (delivered) mirrored += 1; else { rejected += 1; addError(lastCode); }
    }
  }
} finally {
  if (client.isOpen) await client.quit().catch(() => client.disconnect());
}
return [{ json: { schema_version: 1, source: 'CATALOG_APP_BRIDGE', scanned, mirrored, rejected, errors, completed_at: new Date().toISOString(), send: false } }];
